-- Jeu de LecteurTablesReference / EcrivainTablesReference (« Tables de référence », PROC_GTABREF), lot 14 du plan-676a4b19.
-- Codes « G14... ». Les tables aux types de RIG_DEV (RigBaseGreffe\GREFFE\PC_ETAT.cs, PC_ETAT_ZONE.cs, DEMAT_CFEC_AJMJ_TYPE_DEPOT.cs ;
-- Source\BaseDeDonnées\RigDatabase\dbo\Tables\PC_ETAT_HISTO.sql, PC_ETAT_SUIVANT.sql, PC_ETAT_SAISIE.sql, PC_ETAT_DJ_EP.sql), sans
-- leurs cles etrangeres (la base V3 ne les a pas recopiees : l'ecrivain controle les citations avant d'ecrire). DEMAT_CFEC_AJMJ reçoit
-- la definition de PROC_TRANSDOC.sql (joue apres), plus la colonne du type de depot (DEMAT_CFEC_AJMJ.sql : varchar(10) NULL).
IF OBJECT_ID(N'v2.PC_ETAT') IS NULL
    CREATE TABLE v2.PC_ETAT (R_PCETAT_VALEUR varchar(20) NOT NULL PRIMARY KEY, R_PCETAT_LIBELLE_ECRAN varchar(200) NOT NULL,
        R_PCETAT_OUVERTURE bit NOT NULL DEFAULT 0, R_PCETAT_CLOTURE bit NOT NULL, R_PCETAT_MODALITE_REGIME varchar(1) NULL,
        R_PCETAT_MODALITE_PA varchar(1) NULL, R_PCETAT_MODALITE_AJ varchar(1) NULL, R_PCETAT_REGIME_PC_STATS varchar(10) NULL,
        R_PCETAT_CODE_PROC varchar(40) NULL, R_PCETAT_RESOLUTION_PLAN bit NOT NULL DEFAULT 0, R_PCETAT_MAJ_PC bit NOT NULL DEFAULT 1,
        R_PCETAT_AUD_FUTURE bit NOT NULL DEFAULT 0, R_PCETAT_CODE_CLOTURE varchar(5) NULL, R_PCETAT_CONVERSION_LJ bit NOT NULL DEFAULT 0,
        R_PCETAT_EXTENSION bit NOT NULL DEFAULT 0, R_PCETAT_ASAUVER bit NOT NULL DEFAULT 1, R_PCETAT_UTILISABLE_SAISIE bit NOT NULL DEFAULT 1);
IF OBJECT_ID(N'v2.PC_ETAT_ZONE') IS NULL
    CREATE TABLE v2.PC_ETAT_ZONE (R_PCETATZONE_VALEUR varchar(10) NOT NULL PRIMARY KEY, R_PCETATZONE_LIBELLE_ECRAN varchar(50) NOT NULL,
        R_PCETATZONE_SYNONYME varchar(16) NOT NULL, R_PCETATZONE_ISO varchar(20) NOT NULL, R_PCETATZONE_ABREGE_EDIT varchar(5) NULL,
        R_PCETATZONE_SIMPLIFIE_EDIT varchar(100) NOT NULL, R_PCETATZONE_DEVELOPPE_EDIT varchar(1000) NOT NULL,
        R_PCETATZONE_EXHAUSTIF_EDIT varchar(max) NULL, R_PCETATZONE_DATE_CREATION datetime NOT NULL, R_PCETATZONE_AUTEUR_CREATION varchar(50) NULL,
        R_PCETATZONE_DATE_MODIF datetime NULL, R_PCETATZONE_AUTEUR_MODIF varchar(50) NULL, R_PCETATZONE_DATE_DESACTIVATION datetime NULL,
        R_PCETATZONE_ETAT varchar(1) NOT NULL, R_PCETATZONE_UTILISABLE_SAISIE bit NOT NULL, R_PCETATZONE_TABLE varchar(50) NOT NULL,
        R_PCETATZONE_ATTRIBUT varchar(50) NOT NULL, R_PCETATZONE_TYPE varchar(50) NOT NULL);
IF OBJECT_ID(N'v2.DEMAT_CFEC_AJMJ_TYPE_DEPOT') IS NULL
    CREATE TABLE v2.DEMAT_CFEC_AJMJ_TYPE_DEPOT (CFECAJTD_VALEUR varchar(10) NOT NULL PRIMARY KEY, CFECAJTD_LIBELLE_ECRAN varchar(500) NOT NULL,
        CFECAJTD_UTILISABLE_SAISIE bit NOT NULL DEFAULT 1, CFECAJTD_CODE_EVE_PRO varchar(10) NULL, CFECAJTD_DATE_CREATION datetime NOT NULL,
        CFECAJTD_AUTEUR_CREATION varchar(255) NOT NULL, CFECAJTD_DATE_MODIFICATION datetime NULL, CFECAJTD_AUTEUR_MODIFICATION varchar(255) NULL);
IF OBJECT_ID(N'v2.PC_ETAT_HISTO') IS NULL
    CREATE TABLE v2.PC_ETAT_HISTO (PETHT_ID_PETHT int NOT NULL PRIMARY KEY, PETHT_ID_PRCLL int NOT NULL, PETHT_DATE_CREATION datetime NOT NULL,
        PETHT_PCETAT varchar(20) NOT NULL, PETHT_DATE datetime NULL);
IF OBJECT_ID(N'v2.PC_ETAT_SUIVANT') IS NULL
    CREATE TABLE v2.PC_ETAT_SUIVANT (PETSV_ID_PETSV int NOT NULL PRIMARY KEY, PETSV_AVANT varchar(20) NOT NULL, PETSV_APRES varchar(20) NOT NULL,
        PETSV_PAR_DEFAUT bit NOT NULL DEFAULT 0);
IF OBJECT_ID(N'v2.PC_ETAT_SAISIE') IS NULL
    CREATE TABLE v2.PC_ETAT_SAISIE (PETSA_ID_PETSA int NOT NULL PRIMARY KEY, PETSA_ETAT varchar(20) NOT NULL, PETSA_MODALITE_PA varchar(10) NULL,
        PETSA_MODALITE_AJ varchar(10) NULL, PETSA_NUM_ORDRE smallint NOT NULL, PETSA_OBLI bit NOT NULL DEFAULT 0, PETSA_TYPE_SAISIE varchar(10) NOT NULL,
        PETSA_PC_ETAT_ZONE varchar(10) NULL, PETSA_ORGANE_CODE varchar(20) NULL, PETSA_CODE_EVE_PRO_FUTUR varchar(20) NULL,
        PETSA_CODE_EVE_PRO_DELAI smallint NULL, PETSA_CODE_EVE_PRO_PERIODE varchar(10) NULL);
IF OBJECT_ID(N'v2.PC_ETAT_DJ_EP') IS NULL
    CREATE TABLE v2.PC_ETAT_DJ_EP (PETDJ_ID_PETDJ int NOT NULL PRIMARY KEY, PETDJ_ETAT varchar(20) NOT NULL, PETDJ_MODALITE_PA varchar(10) NOT NULL,
        PETDJ_MODALITE_AJ varchar(10) NOT NULL, PETDJ_TYPE_DECISION varchar(50) NULL, PETDJ_CODE_EVE_PRO varchar(50) NULL,
        PETDJ_CODE_EVE_PRO_NI varchar(50) NULL, PETDJ_CODE_EVE_PRO_PM varchar(50) NULL, PETDJ_CODE_EVE_PRO_PP varchar(50) NULL,
        PETDJ_CODE_ACTE_PROCE varchar(3) NULL);
IF OBJECT_ID(N'v2.DEMAT_CFEC_AJMJ') IS NULL
    CREATE TABLE v2.DEMAT_CFEC_AJMJ (CFECAJ_ID_CFECAJ int NOT NULL PRIMARY KEY, CFECAJ_DATE_CREATION datetime NOT NULL,
        CFECAJ_NUMERO_AFF varchar(255) NULL, CFECAJ_NUM_SIREN varchar(255) NULL, CFECAJ_TYPE_DOC varchar(255) NULL,
        CFECAJ_ID_DMND int NOT NULL);
IF COL_LENGTH('v2.DEMAT_CFEC_AJMJ', 'CFECAJ_DEMAT_CFEC_AJMJ_TYPE_DEPOT') IS NULL
    ALTER TABLE v2.DEMAT_CFEC_AJMJ ADD CFECAJ_DEMAT_CFEC_AJMJ_TYPE_DEPOT varchar(10) NULL;

EXEC sp_executesql N'
-- Les etats de PC : G14A (avec ses etats suivants, sa decision et sa saisie, supprimes avec lui), G14B (etat suivant de G14A : supprime
-- refuse tant que G14A le cite, puis accepte), G14H (dans l''historique d''une PC : suppression refusee), G14N (non saisissable : EnCours),
-- G14V (libelle vide : AFaire, nom = le code).
INSERT INTO v2.PC_ETAT (R_PCETAT_VALEUR, R_PCETAT_LIBELLE_ECRAN, R_PCETAT_OUVERTURE, R_PCETAT_CLOTURE, R_PCETAT_UTILISABLE_SAISIE, R_PCETAT_MODALITE_REGIME) VALUES
    (''G14A'', ''ETAT BANC ALPHA'', 1, 0, 1, ''R''), (''G14B'', ''ETAT BANC SUIVANT'', 0, 0, 1, NULL), (''G14H'', ''ETAT BANC HISTO'', 0, 1, 1, NULL),
    (''G14N'', ''ETAT BANC FIGE'', 0, 0, 0, NULL), (''G14V'', '''', 0, 0, 1, NULL);
INSERT INTO v2.PC_ETAT_SUIVANT (PETSV_ID_PETSV, PETSV_AVANT, PETSV_APRES) VALUES (2400971, ''G14A'', ''G14B'');
INSERT INTO v2.PC_ETAT_DJ_EP (PETDJ_ID_PETDJ, PETDJ_ETAT, PETDJ_MODALITE_PA, PETDJ_MODALITE_AJ) VALUES (2400972, ''G14A'', ''A'', ''A'');
INSERT INTO v2.PC_ETAT_SAISIE (PETSA_ID_PETSA, PETSA_ETAT, PETSA_NUM_ORDRE, PETSA_TYPE_SAISIE, PETSA_PC_ETAT_ZONE) VALUES
    (2400973, ''G14A'', 1, ''DATE'', NULL), (2400974, ''G14H'', 1, ''DATE'', ''GZ1'');
INSERT INTO v2.PC_ETAT_HISTO (PETHT_ID_PETHT, PETHT_ID_PRCLL, PETHT_DATE_CREATION, PETHT_PCETAT) VALUES (2400975, 2400999, @aujourdhui, ''G14H'');
-- Les zones : GZ1 (citee par la saisie de G14H : suppression refusee ; copiee par « Dupliquer », sa creation du 03/02/2001 par
-- « BANC ORIGINE » reprise), GZ2 (libre : supprimee). L''etat, le rang de la liste RIG v2 (« 1 » = En vigueur pour tout,
-- SousOPE_HISTORIQUE.cs:39-47) ; une table et un attribut par zone (UX_R_PCETATZONE_TABLE_R_PCETATZONE_ATTRIBUT, PC_ETAT_ZONE.sql).
INSERT INTO v2.PC_ETAT_ZONE (R_PCETATZONE_VALEUR, R_PCETATZONE_LIBELLE_ECRAN, R_PCETATZONE_SYNONYME, R_PCETATZONE_ISO, R_PCETATZONE_SIMPLIFIE_EDIT,
    R_PCETATZONE_DEVELOPPE_EDIT, R_PCETATZONE_DATE_CREATION, R_PCETATZONE_AUTEUR_CREATION, R_PCETATZONE_ETAT, R_PCETATZONE_UTILISABLE_SAISIE,
    R_PCETATZONE_TABLE, R_PCETATZONE_ATTRIBUT, R_PCETATZONE_TYPE) VALUES
    (''GZ1'', ''ZONE BANC CITEE'', ''GZ1'', ''GZ1'', ''zone citee'', ''zone citee'', ''20010203'', ''BANC ORIGINE'', ''1'', 1, ''PROCEDURE_COLLECTIVE'', ''PRCLL_DATE'', ''DATE''),
    (''GZ2'', ''ZONE BANC LIBRE'', ''GZ2'', ''GZ2'', ''zone libre'', ''zone libre'', @aujourdhui, NULL, ''1'', 1, ''PROCEDURE_COLLECTIVE'', ''PRCLL_DATE_FIN'', ''DATE'');
-- Les types de depot AJMJ : GT1 (cite par un depot recu : suppression refusee), GT2 (modifie : date et auteur de modification).
INSERT INTO v2.DEMAT_CFEC_AJMJ_TYPE_DEPOT (CFECAJTD_VALEUR, CFECAJTD_LIBELLE_ECRAN, CFECAJTD_UTILISABLE_SAISIE, CFECAJTD_DATE_CREATION, CFECAJTD_AUTEUR_CREATION) VALUES
    (''GT1'', ''TYPE BANC CITE'', 1, @aujourdhui, ''BANC''), (''GT2'', ''TYPE BANC LIBRE'', 1, @aujourdhui, ''BANC'');
-- Le depot qui cite GT1 : sa demande 2400999 n''existe pas, aucun autre ecran (PROC_TRANSDOC part des demandes) ne le voit.
INSERT INTO v2.DEMAT_CFEC_AJMJ (CFECAJ_ID_CFECAJ, CFECAJ_DATE_CREATION, CFECAJ_ID_DMND, CFECAJ_DEMAT_CFEC_AJMJ_TYPE_DEPOT) VALUES (2400976, @aujourdhui, 2400999, ''GT1'');
', N'@aujourdhui datetime', @aujourdhui;
